// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // fuzzed actor is an address that will call owner(); reference always returns the stored owner (deployer),
    // mutant returns msg.sender so for some actor addresses the returned value will differ. We let fuzzer pick actor.
    function testFuzz_property(address actor) public {
        // keep actor wide but avoid zero address to be safe
        vm.assume(actor != address(0));

        // deployer (this test contract) is the owner stored in reference
        address storedOwner = c.owner(); // should be address(this) in reference

        // call owner() as fuzzed actor
        address returned;
        vm.prank(actor);
        returned = c.owner();

        // General property: for the reference implementation owner() should always return the stored owner
        // regardless of caller; the mutant that returns msg.sender will break this for any actor != storedOwner.
        assertTrue(returned == storedOwner);
    }
}

