    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // fuzz the prospective caller who could be the owner; if owner() always returns deployer
    // then calling owner() should equal the address that deployed (address(this) in setUp).
    // The mutant that returns address(0) will fail this assertion for many fuzzed inputs
    // (specifically whenever the deployer is not address(0), which holds here).
    function testFuzz_property(address someCaller) public {
        // keep wide: only exclude zero address as a meaningless fuzz target for caller
        // (we still want wide coverage; this does not exclude the bug-triggering case)
        // but not required; we include an assume to keep domain sensible
        vm.assume(someCaller != address(0));

        // The general rule: owner() should report the actual owner (deployer set in constructor).
        // We observe via the public owner() getter. The reference returns deployer (address(this) from setUp).
        // The mutant returns address(0), so the following equality will fail on the mutant for our setup.

        address reported = c.owner();
        // exactly one assertion reading c's public surface
        assertTrue(reported == address(this));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), address(this)); }

    // fuzzed param: an arbitrary address that will be used as the caller contract
    function testFuzz_property(address callerContract) public {
        // keep domain wide but avoid zero address which cannot be a contract deployer
        vm.assume(callerContract != address(0));

        // Deploy a small helper contract that will call c.owner() and return what it observes.
        CallerHelper helper = new CallerHelper();

        // The helper will call c.owner() and store the returned address; we then compare
        // that observed value to the reference direct call owner().
        // Direct call by this EOA to owner() should return the stored owner (address(this) from setUp).
        address directOwner = c.owner();

        // Have the helper call c.owner() from a contract context (msg.sender of c will be helper, tx.origin will be this test EOA)
        address observed = helper.callOwner(address(c));

        // The universal property: when owner() reflects the stored owner, both directOwner and observed should be equal
        // because for the correct contract owner() returns the stored owner regardless of whether caller is EOA or contract.
        // For the mutant which returns tx.origin, observed (called via helper contract) will equal tx.origin (this EOA)
        // while directOwner is the stored owner (deployer), so they can differ; thus this assertion will fail for the mutant
        assertTrue(directOwner == observed);
    }
}

// Minimal helper that calls owner() on target contract from a contract context
contract CallerHelper {
    address public lastObserved;

    function callOwner(address target) external returns (address) {
        // call the owner() getter on target and store result
        bytes memory payload = abi.encodeWithSignature("owner()");
        (bool ok, bytes memory ret) = target.call(payload);
        require(ok, "call failed");
        address observed = abi.decode(ret, (address));
        lastObserved = observed;
        return observed;
    }
}

