pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // Fuzz the caller address: the fuzzer will try EOAs; we need a contract at that address, so
    // we deploy a helper proxy from that fuzzed address using vm.prank to make it appear created by it.
    // The distinguishing scenario is when owner() is called via a contract (so msg.sender != tx.origin).
    function testFuzz_property(address fuzzCaller) public {
        // keep wide but avoid zero address which cannot create contracts via prank deploy
        if (fuzzCaller == address(0)) return;

        // Deploy a minimal Caller contract that will call c.owner(). We want the Caller contract's origin
        // to be fuzzCaller, so we perform the creation using vm.prank(fuzzCaller).
        vm.prank(fuzzCaller);
        Caller caller = new Caller(c);

        // Call owner() through the Caller contract. This makes msg.sender == address(caller) and tx.origin == fuzzCaller.
        address returned = caller.callOwner();

        // The reference implementation stores owner as the deployer (set to address(this) in setUp),
        // which is the test contract address. So for ALL inputs (including arbitrary fuzzCaller),
        // when owner() is invoked through any contract, the reference should return the stored owner (address of this test contract).
        // The mutant returns tx.origin (fuzzCaller), so for some fuzzCaller values the returned value will differ and the test will fail on mutant.
        assertTrue(returned == address(this));
    }
}

contract Caller {
    C c;
    constructor(C _c) {
        c = _c;
    }
    function callOwner() external returns (address) {
        return c.owner();
    }
}

