import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address possibleDeployer) public {
        // keep wide but avoid zero address for meaningful deployer
        vm.assume(possibleDeployer != address(0));

        // We need to check the general rule: owner() returns the deployer that constructed the contract.
        // Since setUp deployed c with address(this) as deployer, the correct owner() must equal address(this).
        // The mutant returns address(this) (contract address) which differs from the deployer address for some inputs
        // — here we observe c.owner() and assert it equals the original deployer (address(this)).

        // Call owner() and check result via try/catch to follow rules (though owner() should not revert)
        bool ok;
        address returned;
        try c.owner() returns (address v) {
            ok = true;
            returned = v;
        } catch {
            ok = false;
            returned = address(0);
        }

        // Single assertion: the contract's owner() call must succeed and equal the deployer (address(this))
        assertTrue(ok && returned == address(this));
    }
