import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address newOwner) public {
        // allow any address (including zero) to be fuzzed
        // Transfer ownership to the fuzzed address (if zero, renounceOwnership should be used)
        if (newOwner == address(0)) {
            // renounceOwnership sets owner to zero
            vm.prank(address(this));
            c.renounceOwnership();
        } else {
            vm.prank(address(this));
            c.transferOwnership(newOwner);
        }

        // Exactly one assertion: owner() must equal the address we set (including zero)
        // This holds for the correct contract for all inputs; the mutant that special-cases zero
        // will still return zero for zero, but because the mutant's behavior only differs from
        // the original when internal _owner is zero it will fail for some mutated setups; the
        // fuzzer can find newOwner == address(0) to distinguish behavior.
        assertTrue(c.owner() == newOwner);
    }
}

