pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), address(this)); }

    // fuzzed params: an arbitrary EOA newOwner and an arbitrary EOA txOrigin
    function testFuzz_property(address newOwner, address txOrigin) public {
        vm.assume(newOwner != address(0));
        vm.assume(txOrigin != address(0));
        // Deploy helper contract that will call c.transferOwnership on behalf of its own address.
        Caller caller = new Caller(address(c));

        // Make the helper contract be the current owner by transferring ownership from deployer (setUp owner == address(this))
        // We are the owner (address(this)) in setUp, so transfer ownership to the caller contract now.
        c.transferOwnership(address(caller));

        // Now caller contract will attempt to call transferOwnership(newOwner) but the tx.origin will be txOrigin.
        // To set tx.origin we must have an EOA originate the call; vm.prank changes msg.sender and tx.origin in Foundry.
        // We want tx.origin to be a different EOA than the caller contract's address to trigger difference with mutant.

        // Ensure txOrigin is not the caller contract itself (it won't be) and not the owner (caller)
        vm.assume(txOrigin != address(caller));

        // Execute the call with tx.origin == txOrigin
        vm.prank(txOrigin);
        bool ok;
        try caller.doTransferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The property to assert: In the reference contract, transferOwnership should succeed iff tx.origin == owner()
        // After we set ownership to caller, owner() == address(caller). So reference requires tx.origin == address(caller) for success.
        // But we invoked with tx.origin == txOrigin (an arbitrary EOA). Therefore, for the reference, the call should only succeed when txOrigin == address(caller).
        // Our assertion reads c.owner() to check whether ownership changed to newOwner. This single assertTrue distinguishes the mutant because
        // the mutant (which compares owner() == tx.origin) will only allow success when tx.origin == owner() too — but due to mutated logic comparing tx.origin
        // instead of _msgSender() in onlyOwner, there exist cases where msg.sender (caller contract) is treated as owner in mutant while tx.origin differs, causing different behavior.

        // We assert that if txOrigin != address(caller) then ownership did NOT change (reference enforces that), i.e. owner() != newOwner.
        // This holds for the reference for all inputs; the mutant may incorrectly allow change for some txOrigin != address(caller).
        if (txOrigin != address(caller)) {
            assertTrue(c.owner() != newOwner);
        } else {
            // If txOrigin equals caller (rare fuzz case), the call should succeed and owner becomes newOwner in reference
            assertTrue(c.owner() == newOwner);
        }
    }
}

// Helper contract that simply calls transferOwnership on C
contract Caller {
    C public target;
    constructor(address _target) {
        target = C(_target);
    }
    function doTransferOwnership(address newOwner) external {
        target.transferOwnership(newOwner);
    }
}

