pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), address(this)); }

    // fuzzed params: relayer (a contract) and candidate newOwner EOA
    function testFuzz_property(address relayerAddr, address newOwner) public {
        // Keep addresses non-zero and distinct from contract address
        vm.assume(relayerAddr != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(relayerAddr != address(this));
        vm.assume(newOwner != address(this));

        // Deploy a simple relayer contract at a deterministic address using CREATE2 is complex
        // Instead, deploy a new Relayer and ensure its address is not the zero address
        Relayer r = new Relayer(address(c));
        address rel = address(r);
        vm.assume(rel != address(0));

        // Owner initially is the test contract (set in constructor)
        address ownerBefore = c.owner();
        assertTrue(ownerBefore == address(this));

        // Scenario: the owner (an EOA) can call transferOwnership directly -> reference should allow
        // But we want to exercise a relayed call: tx.origin will be the EOA we choose (tx origin here is this test contract)
        // We make the relayer call transferOwnership(relayedNewOwner) on behalf of owner by invoking the relayer

        // Case A: Direct owner call should succeed on both reference and mutant (owner is msg.sender and tx.origin)
        bool okDirect;
        try c.transferOwnership(newOwner) {
            okDirect = true;
        } catch {
            okDirect = false;
        }
        // On the reference contract this must succeed because msg.sender==_msgSender()==owner()==tx.origin
        assertTrue(okDirect);

        // Reset by transferring ownership back to this test contract if changed by direct call
        // If direct call succeeded, owner now equals newOwner; transfer back via direct call from newOwner cannot be done here.
        // To keep the scenario consistent, redeploy fresh contract state is simpler — but test must use c deployed in setUp.
        // Instead, avoid changing owner by choosing newOwner == ownerBefore for the direct call branch.
        // To ensure we didn't change owner, require newOwner == ownerBefore for direct branch to be trivial.
        // However fuzz must not be constrained too tightly; so instead we perform relayed scenario on a fresh instance.

        // Redeploy a fresh contract to ensure deterministic owner state for relayed test
        c = new C(address(this), address(this));
        // deploy another relayer pointing to new c
        Relayer r2 = new Relayer(address(c));
        rel = address(r2);

        // Now owner is address(this). We will have the relayer contract call transferOwnership(newOwner) with msg.sender = rel and tx.origin = address(this)
        // This models a relayed call where the original tx.origin is the EOA owner but the immediate msg.sender is a contract.

        // Have the relayer attempt the call. Since tx.origin == address(this) (the test), and owner==address(this),
        // the reference contract's onlyOwner modifier checks _msgSender()==owner() (which will be rel), then _checkOwner() uses _msgSender()==owner? In this code _msgSender returns msg.sender; however the variant of concern requires tx.origin==owner to succeed; the reference behaves correctly for this pattern.
        // Execute relayer invocation from this EOA so tx.origin==address(this)
        bool okRelayed;
        try r2.relayTransferOwnership(newOwner) {
            okRelayed = true;
        } catch {
            okRelayed = false;
        }

        // GENERAL RULE (single assertion): On the reference implementation, when the tx.origin equals the current owner (the EOA starting the transaction), a relayed call through a contract that calls transferOwnership must succeed and set owner to the supplied newOwner.
        // We therefore assert that the relayed call returned success AND the owner was updated accordingly.
        // The mutant that compares owner() to tx.origin in the modifier can cause the relayed transferOwnership to behave differently for some relayers or call patterns; the fuzzer will find inputs where mutant fails this assertion.
        assertTrue(okRelayed && c.owner() == newOwner);
    }
}

// Minimal relayer that simply forwards a call to transferOwnership on the target contract
contract Relayer {
    C public target;
    constructor(address _target) {
        target = C(_target);
    }

    // Called by an EOA; will call target.transferOwnership(newOwner) with msg.sender == address(this), tx.origin == EOA
    function relayTransferOwnership(address newOwner) external {
        target.transferOwnership(newOwner);
    }
}

