pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), address(this)); }

    // fuzz parameters: relayerOrigin is an EOA that will be tx.origin, relayerCaller is an address used to deploy the relayer contract (also an EOA), newOwner is the address passed to transferOwnership
    function testFuzz_property(address relayerOrigin, address relayerCaller, address newOwner) public {
        // keep addresses distinct and non-zero to be in meaningful domain
        vm.assume(relayerOrigin != address(0));
        vm.assume(relayerCaller != address(0));
        vm.assume(newOwner != address(0));

        // Setup: make relayerCaller fund relayerOrigin so they can deploy/call (not strictly necessary but keep domain wide)
        vm.deal(relayerOrigin, 1 ether);
        vm.deal(relayerCaller, 1 ether);

        // Deploy a Relayer contract where its creator is relayerCaller, but tx.origin will be relayerOrigin when we have relayerOrigin call into it via tx.origin relayed call.
        // To ensure tx.origin == relayerOrigin while msg.sender inside Relayer is the Relayer contract, we have relayerOrigin call into a helper that in turn calls c.transferOwnership.

        // Deploy Relayer with relayerCaller as deployer
        vm.prank(relayerCaller);
        Relayer r = new Relayer();

        // Now perform the relayed call: tx.origin = relayerOrigin, msg.sender seen by c will be address(r)
        vm.prank(relayerOrigin);
        bool ok;
        try r.relayTransferOwnership(address(c), newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule we assert (reads c's public owner()):
        // In the reference contract, only the EOA equal to owner() (i.e. tx.origin == owner()) may cause transferOwnership to succeed when the call originates from that EOA;
        // Therefore, when tx.origin != current owner, a relayed call (where msg.sender != tx.origin) must not change owner. We check that: if tx.origin != owner_before, then owner() must remain unchanged after the relayed attempt.

        address ownerBefore = c.owner();

        // We already executed the relayed attempt above; check the rule: if relayerOrigin is NOT the ownerBefore, then the reference MUST keep owner unchanged.
        // This assertion is crafted so that the reference C (which uses _msgSender() checks) satisfies it for all inputs, while the mutant (which adds require(owner()==tx.origin)) will for some inputs allow or disallow transfer differently and thus fail this assertion.

        // Single assertion reading c's public surface
        if (relayerOrigin != ownerBefore) {
            // owner must remain the same
            assertTrue(c.owner() == ownerBefore);
        } else {
            // If relayerOrigin == ownerBefore, then a relayed call initiated by owner EOA could succeed and change owner to newOwner.
            // We cannot assume which (some implementations might still revert due to modifier ordering), so accept either outcome by asserting owner is either unchanged or equals newOwner.
            assertTrue(c.owner() == ownerBefore || c.owner() == newOwner);
        }
    }
}

// Minimal relayer helper: its relayTransferOwnership calls transferOwnership on target C, so msg.sender == address(this) inside C while tx.origin is the original EOA that invoked relayTransferOwnership.
contract Relayer {
    function relayTransferOwnership(address target, address newOwner) external {
        C(target).transferOwnership(newOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Relayer relayer;

    function setUp() public { c = new C(address(this), address(this)); relayer = new Relayer(); }

    // fuzz: actor is an arbitrary EOA that will be tx.origin; newOwner is arbitrary
    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        vm.assume(newOwner != address(0));
        // initial owner is address(this) (deployed in setUp). Ensure actor is not already the owner to allow transfer attempts
        vm.assume(actor != address(this));

        // The reference contract requires tx.origin == owner() to pass onlyOwner.
        // We will have the owner (address(this)) call transferOwnership via a contract (relayer) so that msg.sender == relayer but tx.origin == address(this).
        // For the reference C: transferOwnership should succeed only if tx.origin == owner (which holds here since tx.origin will be address(this) when we start the tx as address(this)).
        // For the mutant: it additionally requires owner() == tx.origin inside onlyOwner; this causes differences for relayed calls in some call patterns.

        // First: perform a direct transferOwnership from the owner EOA (address(this)) to newOwner — this must succeed on the reference.
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        // direct call by owner (address(this)) must succeed on the reference for all admissible inputs
        assertTrue(ok);

        // Now set owner back to address(this) to prepare relayed scenario: transfer back if newOwner became owner
        // Only continue if newOwner != address(this)
        if (c.owner() != address(this)) {
            // whoever is owner now is newOwner; make newOwner renounce/transfer back by prank as that address
            // If newOwner is a contract without code this will still work as a prank EOA in test.
            vm.prank(newOwner);
            // try to transfer back; if it fails, skip further checks to avoid locking
            try c.transferOwnership(address(this)) {
            } catch {
                // cannot restore, abort property check (still satisfied earlier assertion)
                return;
            }
        }

        // Now perform a relayed call: we simulate the owner EOA (address(this)) initiating a call into relayer which then calls c.transferOwnership(actor)
        // To simulate tx.origin == address(this) while msg.sender == relayer, we have address(this) call relayer.relayTransfer(c, actor)
        // This creates the call pattern: tx.origin == address(this), msg.sender == relayer when c.transferOwnership is executed.

        // Ensure relayer has no special privileges and is a contract
        vm.prank(address(this));
        relayer.relayTransfer(address(c), actor);

        // After relayed transfer, observe owner. On the reference, only tx.origin == owner() is checked, and tx.origin == address(this) so this must behave like a direct owner call and succeed.
        // The mutant may additionally require owner() == tx.origin in the modifier in a way that relayed calls behave differently; thus there exist inputs where the mutant ends up with a different owner.

        // The single assertion: the owner must equal actor after the relayed call (this is a property the reference enforces for all inputs given the relay from the owner EOA); the mutant will fail for some inputs causing this assertion to fail.
        assertTrue(c.owner() == actor);
    }
}

// minimal relayer: receives a call from an EOA and forwards a call to C
contract Relayer {
    function relayTransfer(address caddr, address newOwner) external {
        C(caddr).transferOwnership(newOwner);
    }
}
